70	int HcclOpBaseAllreduceTest::check_buf_result()
71	{
72	    //获取输出内存
73	    ACLCHECK(aclrtMallocHost((void**)&recv_buff_temp, malloc_kSize));
74	    ACLCHECK(aclrtMemcpy((void*)recv_buff_temp, malloc_kSize, (void*)recv_buff, malloc_kSize, ACL_MEMCPY_DEVICE_TO_HOST));
75	
76	    int ret = 0;
77	    switch(dtype)
78	    {
79	        case HCCL_DATA_TYPE_FP32:
80	            ret = check_buf_result_float((char*)recv_buff_temp, (char*)check_buf, data->count, check);
81	            break;
82	        case HCCL_DATA_TYPE_INT8:
83	        case HCCL_DATA_TYPE_UINT8:
84	            ret = check_buf_result_int8((char*)recv_buff_temp, (char*)check_buf, data->count, check);
85	            break;
86	        case HCCL_DATA_TYPE_INT32:
87	            ret = check_buf_result_int32((char*)recv_buff_temp, (char*)check_buf, data->count, check);
88	            break;
89	        case HCCL_DATA_TYPE_FP16:
90	        case HCCL_DATA_TYPE_INT16:
91	        case HCCL_DATA_TYPE_BFP16:
92	            ret = check_buf_result_half((char*)recv_buff_temp, (char*)check_buf, data->count, check);
93	            break;
94	        case HCCL_DATA_TYPE_INT64:
95	        case HCCL_DATA_TYPE_UINT64:
96	        case HCCL_DATA_TYPE_FP64:
97	            ret = check_buf_result_int64((char*)recv_buff_temp, (char*)check_buf, data->count, check);
98	            break;
99	        default:
100	            ret++;
101	            printf("no match datatype\n");
102	            break;
103	    }
104	    if(ret != 0)
105	    {
106	        check_err++;
107	    }
108	    return 0;
