132	int HcclOpBaseAllreduceTest::hccl_op_base_test() //主函数
133	{
134	    is_data_overflow();
135	
136	    //初始化输入内存
137	    ACLCHECK(aclrtMallocHost((void**)&host_buf, malloc_kSize));
138	    hccl_host_buf_init((char*)host_buf, data->count, dtype, val);
139	    ACLCHECK(aclrtMemcpy((void*)send_buff, malloc_kSize, (void*)host_buf, malloc_kSize, ACL_MEMCPY_HOST_TO_DEVICE));
140	
141	    // 准备校验内存
142	    if (check >= 1) {
143	        ACLCHECK(init_buf_val());
144	    }
145	    // 输入数据量，根据条件判断是否开启仅计算device执行时间
146	 	ACLCHECK(start_profile_device_time_if_needed(16*1024*1024));
147	    //执行集合通信操作
148	    for(int j = 0; j < warmup_iters; ++j) {
149	        HCCLCHECK(HcclAllReduce((void *)send_buff, (void*)recv_buff, data->count, (HcclDataType)dtype, (HcclReduceOp)op_type, hccl_comm, stream));
150	    }
151	
152	    ACLCHECK(aclrtRecordEvent(start_event, stream));
153	
154	    for(int i = 0; i < iters; ++i) {
155	        HCCLCHECK(HcclAllReduce((void *)send_buff, (void*)recv_buff, data->count, (HcclDataType)dtype, (HcclReduceOp)op_type, hccl_comm, stream));
156	    }
157	    //等待stream中集合通信任务执行完成
