652	int HcclTest::parse_cmd_line(int argc, char *argv[])
653	{
654	    int opt = -1;
655	    int longindex = 0;
656	    int ret = 0;
657	    long parsed;
658	    bool is910_95 = IsSupport910_95();
659	    std::string shortopts = is910_95 ? "o:d:b:e:i:f:r:n:w:c:p:a:t:m:h" : "o:d:b:e:i:f:r:n:w:c:p:z:s:t:m:h";
660	    std::vector<struct option> longopts = build_longopts(is910_95);
661	
662	    const char *opModeEnv = getenv("HCCL_OP_EXPANSION_MODE");
663	    if (is910_95 && opModeEnv == nullptr) { // 需要确保环境变量未配置
664	        accelerator_config = 6; // 910_95场景，修改默认加速器模式为CCU_SCHED
665	    }
666	    while (-1 != (opt = getopt_long(argc, argv, shortopts.c_str(), longopts.data(), &longindex))) {
667	        ret = parse_opt(opt);
668	        if (ret != 0) {
669	            return ret;
670	        }
671	    }
672	
673	    if (optind < argc) {
674	        printf("non-option ARGV-elements: ");
675	        while (optind < argc) {
676	            printf("%s ", argv[optind++]);
677	        }
678	        printf("\n");
679	        return -1;
680	    }
681	
682	    return 0;
683	}
