800	                 (data->step_factor <= 1.0 ? data->data_size += data->step_bytes
801	                                           : data->data_size *= data->step_factor)) {
802	            }
803	        }
804	
805	        size_t send_bytes = 0;
806	        size_t recv_bytes = 0;
807	        // 设置内存对齐大小 默认对齐128字节，开启zero_copy，默认对齐2M
808	        prop = {aclrtMemHandleType::ACL_MEM_HANDLE_TYPE_NONE,
809	            aclrtMemAllocationType::ACL_MEM_ALLOCATION_TYPE_PINNED,
810	            use_ddr_mem(),
811	            {dev_id, aclrtMemLocationType::ACL_MEM_LOCATION_TYPE_DEVICE},
812	            0};
813	        auto status =
814	            aclrtMemGetAllocationGranularity(&prop, ACL_RT_MEM_ALLOC_GRANULARITY_MINIMUM, &physicalGranularity);
815	        if (status != ACL_SUCCESS) {
816	            physicalGranularity = 2 * 1024 * 1024;
817	        }
818	        get_buff_size(send_bytes, recv_bytes);
819	        reserve_mem = get_reseved_size(send_bytes, recv_bytes, physicalGranularity);
820	        HCCLCHECK(static_cast<HcclResult>(check_alloc_memory_size(reserve_mem)));
821	        status = aclrtReserveMemAddress(&vir_ptr, reserve_mem, 0, NULL, 1);
822	        if (status != ACL_SUCCESS) {
823	            printf("[%s][%d] aclrtReserveMemAddress failed.\n", __FUNCTION__, __LINE__);
824	            goto error_device_init;
825	        }
826	    }
827	
828	    begin = system_clock::now();
829	    ret = init_hcclComm();
830	    if (ret != 0) {
831	        goto error_reserve_memAddress;
832	    }
833	
834	    diff = duration_cast<microseconds>(system_clock::now() - begin).count();
835	    HCCL_TEST_LOG("init_hcclComm success, take time[%lld us].\n", diff);
836	
837	    if (enable_zero_copy) {
838	        auto status = HcclCommSetMemoryRange(hccl_comm, vir_ptr, reserve_mem, 0, 0);
839	        if (status != HCCL_SUCCESS) {
840	            printf("[%s][%d] HcclCommSetMemoryRange failed.\n", __FUNCTION__, __LINE__);
841	            goto error_reserve_lpcMemory;
842	        }
843	    }
844	    ret = opbase_test_by_data_size();
845	
846	error_reserve_lpcMemory:
847	    if (enable_zero_copy) {
848	        ret = HcclCommUnsetMemoryRange(hccl_comm, vir_ptr);
849	    }
850	error_destory_comm:
851	    ret = HcclCommDestroy(hccl_comm);
852	error_reserve_memAddress:
853	    if (enable_zero_copy) {
854	        ret = aclrtReleaseMemAddress(vir_ptr);
