906	int HcclTest::init_hcclComm()
907	{
908	    // 将root_info广播到通信域内的其他rank
909	    MPI_Request request;
910	    MPI_Status status;
911	    // 在root_rank获取root_info
912	    if (rank_id == root_rank) {
913	        printf("the minbytes is %llu, maxbytes is %llu, iters is %d, warmup_iters is %d\n",
914	            data->min_bytes,
915	            data->max_bytes,
916	            iters,
917	            warmup_iters);
918	        HcclResult getRootInfo = HcclGetRootInfo(&comm_id);
919	        if (getRootInfo == HCCL_SUCCESS) {
920	            // 将root_info广播到通信域内的其他rank
921	            MPI_Ibcast(&comm_id, HCCL_ROOT_INFO_BYTES, MPI_CHAR, root_rank, MPI_COMM_WORLD, &request);
922	        } else {
923	            // 通知其他rank获取root_info失败
924	            char send_str[] = "invalid";
925	            MPI_Ibcast(send_str, HCCL_ROOT_INFO_BYTES, MPI_CHAR, root_rank, MPI_COMM_WORLD, &request);
926	        }
927	        MPI_Wait(&request, &status);
928	        if (getRootInfo != HCCL_SUCCESS) {
929	            printf("Process %d HcclGetRootInfo failed, notify other process to exit\n", root_rank);
930	            return getRootInfo;
931	        }
932	    } else {
933	        // 非根进程接收数据
934	        MPI_Ibcast(&comm_id, HCCL_ROOT_INFO_BYTES, MPI_CHAR, root_rank, MPI_COMM_WORLD, &request);
935	        MPI_Wait(&request, &status);
936	        if (strcmp(reinterpret_cast<const char *>(&comm_id), "invalid") == 0) {
937	            // 检测到无效数据
938	            printf("Process %d received invalid data from root process %d\n", rank_id, root_rank);
939	            return -1;
940	        }
941	    }
942	    // 初始化集合通信域
943	    if (nslb_flag == 1) {
944	        // HCCL_COMM_CONFIG_RESERVED 字段小于7，代表当前版本未适配DP场景
945	        if (HcclGetCommConfigCapability() < NSLBDP_SUPPORT_VERSION) {
946	            printf("The current version of hccl_test does not support the nslb-dp capability.\n");
947	            HCCLCHECK(HcclCommInitRootInfo(rank_size, &comm_id, rank_id, &hccl_comm));
948	            return 0;
949	        }
950	        // 配置nslb使能的场景 == 1 才生效
951	        HcclCommConfig config= { 0 };
952	        HcclCommConfigInit(&config);
953	        const char *ip = comm_id.internal;
954	        // 当前port字段目的只是提供一个拼接的id， 不具有实际意义
955	        uint32_t port = 11;
956	        uint32_t ipaddress = (uint32_t)inet_addr(ip);
957	        config.hcclWorldRankID = rank_id;
958	        config.hcclJobID = ((uint64_t)port << NSLBDP_PORT_OFFSET) | (uint64_t)ipaddress;
959	        config.hcclOpExpansionMode = accelerator_config;
960	        HCCLCHECK(HcclCommInitRootInfoConfig(rank_size, &comm_id, rank_id, &config, &hccl_comm));
961	    } else {
962	        auto ret = init_hcclComm_without_nslb();
963	        if (ret != 0) {return ret;}
964	    }
965	
966	    return 0;
967	}
