1044	int HcclTest::prepare_zero_copy(const size_t &send_bytes, const size_t &recv_bytes)
1045	{
1046	    if (!enable_zero_copy || ((send_bytes + recv_bytes) == 0)) {
1047	        return HCCL_SUCCESS;
1048	    }
1049	    static size_t current_alloc_phy_mem_byte = 0;
1050	    auto malloc_mem = get_reseved_size(send_bytes, recv_bytes, physicalGranularity);
1051	    if (current_alloc_phy_mem_byte >= malloc_mem) {
1052	        return HCCL_SUCCESS;
1053	    }
1054	    int status = 0;
1055	    aclrtDrvMemHandle mem_handle;
1056	    status = aclrtMallocPhysical(&mem_handle, malloc_mem - current_alloc_phy_mem_byte, &prop, 0);
1057	    if (status != ACL_SUCCESS) {
1058	        printf("[%s][%d] aclrtMallocPhysical failed.\n", __FUNCTION__, __LINE__);
1059	        goto enableerr0;
1060	    }
1061	    status = aclrtMapMem(reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(vir_ptr) + current_alloc_phy_mem_byte),
1062	        malloc_mem - current_alloc_phy_mem_byte,
1063	        0,
1064	        mem_handle,
1065	        0);
1066	    if (status != ACL_SUCCESS) {
1067	        printf("[%s][%d] aclrtMapMem failed.\n", __FUNCTION__, __LINE__);
1068	        goto enableerr0;
1069	    }
1070	    status = HcclCommActivateCommMemory(hccl_comm,
1071	        reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(vir_ptr) + current_alloc_phy_mem_byte),
1072	        malloc_mem - current_alloc_phy_mem_byte,
1073	        0,
1074	        mem_handle,
1075	        0);
1076	    if (status != 0) {
1077	        printf("[%s][%d] HcclCommValidMemory failed.\n", __FUNCTION__, __LINE__);
1078	        goto enableerr0;
1079	    }
1080	    phy_alloc_mem_handle.push_back(std::make_pair(
1081	        reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(vir_ptr) + current_alloc_phy_mem_byte), mem_handle));
1082	    current_alloc_phy_mem_byte = malloc_mem;
1083	    return 0;
1084	
1085	enableerr0:
1086	    for (auto &&mem_handle : phy_alloc_mem_handle) {
1087	        HCCLCHECK(HcclCommDeactivateCommMemory(hccl_comm, mem_handle.first));
1088	        ACLCHECK(aclrtUnmapMem(mem_handle.first));
1089	        ACLCHECK(aclrtFreePhysical(mem_handle.second));
1090	    }
1091	    phy_alloc_mem_handle.clear();
1092	    return status;
1093	}
