1149	int HcclTest::hccl_mem_alloc(size_t size, void **ptr, aclrtDrvMemHandle *handle)
1150	{
1151	    if (ptr == nullptr || size == 0 || handle == nullptr) {
1152	        printf("[%s][%d] Invalid parameter: ptr[%p], size[%zu].\n", __FUNCTION__, __LINE__, ptr, size);
1153	        return HCCL_E_PARA;
1154	    }
1155	
1156	    int32_t deviceId;
1157	    ACLCHECK(aclrtGetDevice(&deviceId));
1158	    aclrtPhysicalMemProp prop;
1159	    fill_physical_mem_prop(prop, deviceId);
1160	
1161	    size_t allocSize = size;
1162	    size_t granularity = 0;
1163	    aclError ret = aclrtMemGetAllocationGranularity(&prop, ACL_RT_MEM_ALLOC_GRANULARITY_RECOMMENDED, &granularity);
1164	    if (ret != ACL_SUCCESS || granularity == 0) {
1165	        printf("[%s][%d] GetAllocationGranularity failed.\n", __FUNCTION__, __LINE__);
1166	        return HCCL_E_RUNTIME;
1167	    }
1168	    allocSize = (allocSize + granularity - 1) / granularity * granularity;
1169	
1170	    if (IsSupport910_95()) {
1171	        aclError allocRet = aclrtMalloc(ptr, allocSize, ACL_MEM_MALLOC_HUGE_ONLY);
1172	        if(allocRet != ACL_SUCCESS) {
1173	            printf("[%s][%d] aclrtMalloc failed.\n", __FUNCTION__, __LINE__);
1174	            if (*ptr != nullptr) {
1175	                aclrtFree(*ptr);
1176	                *ptr = nullptr;
1177	            }
1178	            return HCCL_E_RUNTIME;
1179	        }
1180	        return HCCL_SUCCESS;
1181	    }
1182	
1183	    ret = aclrtReserveMemAddress(ptr, allocSize, 0, nullptr, 1);
1184	    if (ret != ACL_SUCCESS) {
1185	        printf("[%s][%d] aclrtReserveMemAddress failed.\n", __FUNCTION__, __LINE__);
1186	        return HCCL_E_RUNTIME;
1187	    }
1188	    void *virPtr = *ptr;
1189	    ret = aclrtMallocPhysical(handle, allocSize, &prop, 0);
1190	    if(ret != ACL_SUCCESS) {
1191	        printf("[%s][%d] aclrtMallocPhysical failed.\n", __FUNCTION__, __LINE__);
1192	        aclrtReleaseMemAddress(virPtr);
1193	        return HCCL_E_RUNTIME;
1194	    }
1195	    ret = aclrtMapMem(virPtr, allocSize, 0, *handle, 0);
1196	    if(ret != ACL_SUCCESS) {
1197	        printf("[%s][%d] aclrtMapMem failed.\n", __FUNCTION__, __LINE__);
1198	        aclrtFreePhysical(*handle);
1199	        aclrtReleaseMemAddress(virPtr);
1200	        return HCCL_E_RUNTIME;
1201	    }
1202	
1203	    return HCCL_SUCCESS;
1204	}
